--
-- Table structure for table `analytics_daily_pages`
--

DROP TABLE IF EXISTS `analytics_daily_pages`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `analytics_daily_pages` (
  `website_id` int(10) unsigned NOT NULL,
  `day` date NOT NULL,
  `path` varchar(500) NOT NULL,
  `path_hash` char(32) NOT NULL,
  `title` varchar(190) DEFAULT NULL,
  `pageviews` int(10) unsigned NOT NULL DEFAULT 0,
  `visitors` int(10) unsigned NOT NULL DEFAULT 0,
  `entries` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'sessions that started on this page',
  `bounces` int(10) unsigned NOT NULL DEFAULT 0,
  `duration_sum` int(10) unsigned NOT NULL DEFAULT 0,
  `duration_n` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`website_id`,`day`,`path_hash`),
  CONSTRAINT `fk_adp_site` FOREIGN KEY (`website_id`) REFERENCES `websites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

