DROP TABLE IF EXISTS `email_queue`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `email_queue` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int(10) unsigned DEFAULT NULL,
  `to_email` varchar(190) NOT NULL,
  `to_name` varchar(150) DEFAULT NULL,
  `cc` varchar(255) DEFAULT NULL,
  `bcc` varchar(255) DEFAULT NULL,
  `from_name` varchar(150) DEFAULT NULL,
  `from_email` varchar(190) DEFAULT NULL,
  `reply_to` varchar(190) DEFAULT NULL,
  `subject` varchar(250) NOT NULL,
  `body` mediumtext NOT NULL,
  `category` varchar(40) NOT NULL DEFAULT 'general',
  `template` varchar(40) DEFAULT NULL,
  `ref_id` int(10) unsigned DEFAULT NULL,
  `status` enum('pending','sent','failed') NOT NULL DEFAULT 'pending',
  `attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `next_attempt_at` datetime DEFAULT NULL,
  `last_error` varchar(1000) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `sent_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_queue_status` (`status`,`created_at`),
  KEY `idx_queue_ref` (`category`,`ref_id`),
  KEY `idx_queue_tenant` (`tenant_id`),
  KEY `idx_queue_due` (`status`,`next_attempt_at`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=454 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

