--
-- Table structure for table `forms`
--

DROP TABLE IF EXISTS `forms`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `forms` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int(10) unsigned DEFAULT NULL,
  `website_id` int(10) unsigned NOT NULL,
  `source` enum('manual','auto') NOT NULL DEFAULT 'manual' COMMENT 'auto = discovered by the crawler',
  `name` varchar(150) NOT NULL,
  `page_url` varchar(255) NOT NULL,
  `page_id` int(10) unsigned DEFAULT NULL COMMENT 'website_pages.id of the primary page',
  `page_title` varchar(190) DEFAULT NULL,
  `fingerprint` char(40) DEFAULT NULL COMMENT 'sha1 of stable form identity (dedupe)',
  `form_title` varchar(190) DEFAULT NULL COMMENT 'Title detected on the page / popup',
  `form_dom_id` varchar(120) DEFAULT NULL,
  `technology` varchar(40) DEFAULT NULL COMMENT 'Contact Form 7, WPForms, Elementor, Custom PHP, JotForm…',
  `fields_json` text DEFAULT NULL COMMENT '[{name,type,label,required}]',
  `field_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `submit_label` varchar(120) DEFAULT NULL,
  `action_url` varchar(500) DEFAULT NULL COMMENT 'Form action discovered on the page (informational – tests always use the live page action)',
  `in_iframe` tinyint(1) NOT NULL DEFAULT 0,
  `iframe_src` varchar(500) DEFAULT NULL,
  `discovery_status` enum('active','removed') NOT NULL DEFAULT 'active',
  `discovered_by` enum('http','browser') DEFAULT NULL,
  `first_discovered_at` datetime DEFAULT NULL,
  `last_discovered_at` datetime DEFAULT NULL,
  `removed_at` datetime DEFAULT NULL,
  `missed_scans` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `form_url` varchar(255) DEFAULT NULL COMMENT 'Action/handler URL. Blank = same as page URL',
  `form_type` varchar(40) NOT NULL DEFAULT 'Contact',
  `form_kind` enum('normal','popup','ajax','wordpress') NOT NULL DEFAULT 'normal',
  `engine` enum('auto','http','browser') NOT NULL DEFAULT 'auto',
  `wp_plugin` varchar(30) DEFAULT NULL COMMENT 'Detected WordPress form plugin',
  `popup_trigger` varchar(255) DEFAULT NULL COMMENT 'CSS selector (or text=...) of the element that opens the popup',
  `popup_selector` varchar(255) DEFAULT NULL,
  `form_selector` varchar(255) DEFAULT NULL,
  `submit_selector` varchar(255) DEFAULT NULL,
  `method` enum('POST','GET') NOT NULL DEFAULT 'POST',
  `ajax` tinyint(1) NOT NULL DEFAULT 0,
  `recipient_email` varchar(255) DEFAULT NULL,
  `cc_email` varchar(255) DEFAULT NULL,
  `bcc_email` varchar(255) DEFAULT NULL,
  `smtp_provider` varchar(120) DEFAULT NULL,
  `auto_test` tinyint(1) NOT NULL DEFAULT 1,
  `test_interval` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Minutes between automatic tests. 0 = use global setting',
  `test_payload` text DEFAULT NULL COMMENT 'field=value per line; supports {{test_email}} {{token}} {{name}} {{phone}} {{message}}',
  `test_name` varchar(120) DEFAULT NULL,
  `test_email` varchar(190) DEFAULT NULL,
  `test_phone` varchar(40) DEFAULT NULL,
  `test_message` varchar(500) DEFAULT NULL,
  `test_email_recipient` varchar(190) DEFAULT NULL COMMENT 'Mailbox that should receive the form email (verified over IMAP when configured)',
  `verify_email` tinyint(1) NOT NULL DEFAULT 0,
  `captcha_type` enum('none','recaptcha','hcaptcha','turnstile','other') NOT NULL DEFAULT 'none' COMMENT 'CAPTCHA / anti-bot protection configured by the admin',
  `captcha_mode` enum('detect','test_url','test_field') NOT NULL DEFAULT 'detect' COMMENT 'detect = report Blocked by CAPTCHA (never bypass); test_url = owner-approved test/staging page without CAPTCHA; test_field = owner-approved test parameter',
  `captcha_test_url` varchar(255) DEFAULT NULL COMMENT 'Owner-approved test / staging page used for submission tests',
  `captcha_test_field` varchar(255) DEFAULT NULL COMMENT 'Owner-approved test parameter(s) name=value added to test submissions',
  `captcha_detected` varchar(30) DEFAULT NULL COMMENT 'CAPTCHA type detected during the last test',
  `captcha_seen_count` int(10) unsigned NOT NULL DEFAULT 0,
  `success_match` varchar(255) DEFAULT NULL COMMENT 'Text or URL fragment expected on success',
  `expect_http_code` smallint(5) unsigned DEFAULT NULL COMMENT 'Expected HTTP response code (blank = any 2xx/3xx)',
  `expect_response` varchar(255) DEFAULT NULL COMMENT 'Text / JSON fragment expected in the HTTP or AJAX response',
  `expect_redirect` varchar(255) DEFAULT NULL COMMENT 'Expected redirect URL (or fragment) after submission',
  `status` enum('failed','captcha_blocked','not_tested','working','disabled','removed') NOT NULL DEFAULT 'not_tested',
  `last_tested_at` datetime DEFAULT NULL,
  `next_test_at` datetime DEFAULT current_timestamp(),
  `test_job_id` bigint(20) unsigned DEFAULT NULL,
  `last_result` enum('success','failed','blocked') DEFAULT NULL,
  `last_response_code` smallint(5) unsigned DEFAULT NULL,
  `last_error` varchar(500) DEFAULT NULL,
  `last_failure_reason` varchar(120) DEFAULT NULL,
  `last_outcome` varchar(30) DEFAULT NULL COMMENT 'working / email_unknown / failed / captcha_blocked / interference / timeout / config_error / js_error / network_error',
  `last_page_ok` tinyint(1) DEFAULT NULL,
  `last_form_found` tinyint(1) DEFAULT NULL,
  `last_email_received` enum('yes','no','unknown') DEFAULT NULL,
  `failed_tests` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Consecutive failed tests',
  `last_success_at` datetime DEFAULT NULL,
  `last_failed_at` datetime DEFAULT NULL,
  `total_failures` int(10) unsigned NOT NULL DEFAULT 0,
  `total_success` int(10) unsigned NOT NULL DEFAULT 0,
  `total_downtime` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'seconds, accumulated from resolved incidents',
  `last_engine` enum('http','browser') DEFAULT NULL,
  `last_final_url` varchar(500) DEFAULT NULL,
  `last_ajax_status` smallint(5) unsigned DEFAULT NULL,
  `last_response_text` varchar(500) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_forms_website` (`website_id`),
  KEY `idx_forms_status` (`status`),
  KEY `idx_forms_tested` (`last_tested_at`),
  KEY `idx_forms_website_status` (`website_id`,`status`),
  KEY `idx_forms_auto_tested` (`auto_test`,`status`,`last_tested_at`),
  KEY `idx_forms_name` (`name`),
  KEY `idx_forms_status_tested` (`status`,`last_tested_at`),
  KEY `idx_forms_kind_status` (`form_kind`,`status`),
  KEY `idx_forms_failed_at` (`last_failed_at`),
  KEY `idx_forms_fingerprint` (`website_id`,`fingerprint`),
  KEY `idx_forms_source` (`source`,`discovery_status`),
  KEY `idx_forms_tenant` (`tenant_id`,`status`),
  KEY `idx_forms_tenant_tested` (`tenant_id`,`last_tested_at`),
  KEY `idx_forms_tenant_created` (`tenant_id`,`created_at`),
  KEY `idx_forms_due_test` (`auto_test`,`status`,`next_test_at`),
  FULLTEXT KEY `ft_forms` (`name`,`page_url`,`recipient_email`),
  CONSTRAINT `fk_forms_website` FOREIGN KEY (`website_id`) REFERENCES `websites` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=120300 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
